def unpack_state_casadi(x, K, M):
    Nu = K * (K + 1) // 2
    Q_u = x[:Nu]
    R_flat = x[Nu:Nu + K*M]
    v = x[Nu + K*M:]

    Q = ca.MX.zeros(K, K)
    idx = 0
    for i in range(K):
        for j in range(i, K):
            Q[i, j] = Q_u[idx]
            Q[j, i] = Q_u[idx]
            idx += 1

    R = ca.reshape(R_flat, K, M)
    return Q, R, v

def pack_state_casadi(Q, R, v, K, M):
    Q_u = []
    for i in range(K):
        for j in range(i, K):
            Q_u.append(Q[i, j])
    return ca.vertcat(*Q_u, ca.reshape(R, K*M, 1), v)




