def eta_l2_penalty(ETA, weight=1e-6):
    return weight * ca.sumsqr(ETA)

def diagQ_barrier_penalty(X_nodes, K, M, eps=1e-6, weight=1.0):
    """
    Penalize diag(Q) dropping below eps at shooting nodes.
    X_nodes: list of MX vectors (states at nodes)
    """
    pen = 0
    for x in X_nodes:
        d = diag_Q_from_packed(x, K, M)
        pen += ca.sumsqr(softplus(eps - d))  # soft barrier
    return weight * pen

def one_plus_diagSigma_barrier(X_nodes, K, M, T, sigma2, eps=1e-6, weight=1.0):
    pen = 0
    Tdm = T  # assume DM or MX constant
    for x in X_nodes:
        Q, R, v = unpack_state_casadi(x, K, M)

        # Sigma = sigma2 * [[Q, R],[R^T, T]]
        Sigma = sigma2 * ca.vertcat(
            ca.horzcat(Q, R),
            ca.horzcat(R.T, Tdm)
        )
        d = ca.diag(Sigma)
        pen += ca.sumsqr(softplus(eps - (1 + d)))   # keep 1+diag(Sigma) >= eps
    return weight * pen

