def nearest_indices(a, b):
    a = np.asarray(a)
    b = np.asarray(b)

    # Compute pairwise absolute differences
    diff = np.abs(a[:, None] - b[None, :])

    # For each element of a, find index of closest in b
    idx = np.argmin(diff, axis=1)

    return idx

