def I3_numpy(q_bb, q_rr, q_zz, q_br, q_bz, q_rz):
    """Three-point integral (numpy)."""
    Lambda_3 = max((1.0 + q_rr) * (1.0 + q_zz) - q_rz**2, 1e-12)
    numerator = q_rz * (1.0 + q_bb) - q_br * q_bz
    denominator = np.sqrt(Lambda_3) * (1.0 + q_bb)
    return (2.0 / np.pi) * numerator / (denominator + 1e-12)

def compute_F_numpy(Q, R, T, v, b, K, M):
    """Compute F_{ik} = E[δ_i λ_k] (numpy version)."""
    F = np.zeros((K, K))
    for i in range(K):
        for k in range(K):
            student_sum = 0.0
            for j in range(K):
                student_sum += v[j] * I3_numpy(Q[k,k], Q[i,i], Q[j,j], Q[k,i], Q[k,j], Q[i,j])
            teacher_sum = 0.0
            for n in range(M):
                teacher_sum += b[n] * I3_numpy(Q[k,k], Q[i,i], T[n,n], Q[k,i], R[k,n], R[i,n])
            F[i, k] = v[i] * (student_sum - teacher_sum)
    return F

def compute_H_numpy(Q, R, T, v, b, K, M):
    """Compute H_{in} = E[δ_i ρ_n] (numpy version)."""
    H = np.zeros((K, M))
    for i in range(K):
        for n in range(M):
            student_sum = 0.0
            for j in range(K):
                student_sum += v[j] * I3_numpy(T[n,n], Q[i,i], Q[j,j], R[i,n], R[j,n], Q[i,j])
            teacher_sum = 0.0
            for m in range(M):
                teacher_sum += b[m] * I3_numpy(T[n,n], Q[i,i], T[m,m], R[i,n], T[n,m], R[i,m])
            H[i, n] = v[i] * (student_sum - teacher_sum)
    return H

def compute_G_numpy(Q, R, T, v, b, K, M):
    """Compute G_{ik} = E[δ_i δ_k] (numpy version)."""
    G = np.zeros((K, K))
    for i in range(K):
        for k in range(K):
            # Student-student
            ss_sum = 0.0
            for j in range(K):
                for l in range(K):
                    ss_sum += v[j] * v[l] * I4_numpy(
                        Q[j,j], Q[l,l], Q[i,i], Q[k,k],
                        Q[j,l], Q[j,i], Q[j,k], Q[l,i], Q[l,k], Q[i,k])
            # Teacher-teacher
            tt_sum = 0.0
            for n in range(M):
                for m in range(M):
                    tt_sum += b[n] * b[m] * I4_numpy(
                        T[n,n], T[m,m], Q[i,i], Q[k,k],
                        T[n,m], R[i,n], R[k,n], R[i,m], R[k,m], Q[i,k])
            # Mixed
            mixed_sum = 0.0
            for j in range(K):
                for n in range(M):
                    mixed_sum += v[j] * b[n] * I4_numpy(
                        Q[j,j], T[n,n], Q[i,i], Q[k,k],
                        R[j,n], Q[j,i], Q[j,k], R[i,n], R[k,n], Q[i,k])
            G[i, k] = v[i] * v[k] * (ss_sum + tt_sum - 2.0 * mixed_sum)
    return G

def generalization_error_numpy(Q, R, T, v, b, K, M):
    """Compute generalization error (numpy version)."""
    eps_g = 0.0
    for j in range(K):
        for l in range(K):
            eps_g += v[j] * v[l] * I2_numpy(Q[j,j], Q[l,l], Q[j,l])
    for n in range(M):
        for m in range(M):
            eps_g += b[n] * b[m] * I2_numpy(T[n,n], T[m,m], T[n,m])
    for j in range(K):
        for n in range(M):
            eps_g -= 2.0 * v[j] * b[n] * I2_numpy(Q[j,j], T[n,n], R[j,n])
    return eps_g


