def I2_numpy_old(q_bb, q_rr, q_br):
    """Two-point integral (numpy)."""
    q_bb = max(q_bb, 1e-6)
    q_rr = max(q_rr, 1e-6)

    denom = np.sqrt((1.0 + q_bb) * (1.0 + q_rr))
    arg = np.clip(q_br / (denom + 1e-12), -1.0 + 1e-7, 1.0 - 1e-7)
    return (2.0 / np.pi) * np.arcsin(arg)


def I3_numpy_old(q_bb, q_rr, q_zz, q_br, q_bz, q_rz):
    """Three-point integral (numpy)."""
    Lambda_3 = max((1.0 + q_rr) * (1.0 + q_zz) - q_rz**2, 1e-12)
    numerator = q_rz * (1.0 + q_bb) - q_br * q_bz
    denominator = np.sqrt(Lambda_3) * (1.0 + q_bb)
    return (2.0 / np.pi) * numerator / (denominator + 1e-12)


def I4_numpy_old(q_bb, q_rr, q_zz, q_tt, q_br, q_bz, q_bt, q_rz, q_rt, q_zt):
    """Four-point integral (numpy)."""
    Lambda_4 = max((1.0 + q_zz) * (1.0 + q_tt) - q_zt**2, 1e-12)

    Lambda_0 = (Lambda_4 * q_br 
                - q_bt * q_rt * (1.0 + q_zz) 
                - q_bz * q_rz * (1.0 + q_tt)
                + q_zt * q_bz * q_rt 
                + q_zt * q_rz * q_bt)

    Lambda_1 = max(Lambda_4 * (1.0 + q_bb) 
                   - q_bt**2 * (1.0 + q_zz) 
                   - q_bz**2 * (1.0 + q_tt)
                   + 2.0 * q_zt * q_bz * q_bt, 1e-12)

    Lambda_2 = max(Lambda_4 * (1.0 + q_rr) 
                   - q_rt**2 * (1.0 + q_zz) 
                   - q_rz**2 * (1.0 + q_tt)
                   + 2.0 * q_zt * q_rz * q_rt, 1e-12)

    arg = np.clip(Lambda_0 / np.sqrt(Lambda_1 * Lambda_2), -1.0 + 1e-7, 1.0 - 1e-7)
    return (4.0 / (np.pi**2 * np.sqrt(Lambda_4))) * np.arcsin(arg)


def compute_F_numpy_old(Q, R, T, v, b, K, M):
    """Compute F_{ik} = E[δ_i λ_k] (numpy version)."""
    F = np.zeros((K, K))
    for i in range(K):
        for k in range(K):
            student_sum = 0.0
            for j in range(K):
                student_sum += v[j] * I3_numpy_old(Q[k,k], Q[i,i], Q[j,j], Q[k,i], Q[k,j], Q[i,j])
            teacher_sum = 0.0
            for n in range(M):
                teacher_sum += b[n] * I3_numpy_old(Q[k,k], Q[i,i], T[n,n], Q[k,i], R[k,n], R[i,n])
            F[i, k] = v[i] * (student_sum - teacher_sum)
    return F


def compute_H_numpy_old(Q, R, T, v, b, K, M):
    """Compute H_{in} = E[δ_i ρ_n] (numpy version)."""
    H = np.zeros((K, M))
    for i in range(K):
        for n in range(M):
            student_sum = 0.0
            for j in range(K):
                student_sum += v[j] * I3_numpy_old(T[n,n], Q[i,i], Q[j,j], R[i,n], R[j,n], Q[i,j])
            teacher_sum = 0.0
            for m in range(M):
                teacher_sum += b[m] * I3_numpy_old(T[n,n], Q[i,i], T[m,m], R[i,n], T[n,m], R[i,m])
            H[i, n] = v[i] * (student_sum - teacher_sum)
    return H


def compute_J_numpy_old(Q, R, T, v, b, K, M):
    """Compute J_i = E[e g(λ_i)] (numpy version)."""
    J = np.zeros(K)
    for i in range(K):
        student_sum = sum(v[j] * I2_numpy_old(Q[j,j], Q[i,i], Q[j,i]) for j in range(K))
        teacher_sum = sum(b[n] * I2_numpy_old(T[n,n], Q[i,i], R[i,n]) for n in range(M))
        J[i] = student_sum - teacher_sum
    return J


def compute_G_numpy_old(Q, R, T, v, b, K, M):
    """Compute G_{ik} = E[δ_i δ_k] (numpy version)."""
    G = np.zeros((K, K))
    for i in range(K):
        for k in range(K):
            # Student-student
            ss_sum = 0.0
            for j in range(K):
                for l in range(K):
                    ss_sum += v[j] * v[l] * I4_numpy_old(
                        Q[j,j], Q[l,l], Q[i,i], Q[k,k],
                        Q[j,l], Q[j,i], Q[j,k], Q[l,i], Q[l,k], Q[i,k])
            # Teacher-teacher
            tt_sum = 0.0
            for n in range(M):
                for m in range(M):
                    tt_sum += b[n] * b[m] * I4_numpy_old(
                        T[n,n], T[m,m], Q[i,i], Q[k,k],
                        T[n,m], R[i,n], R[k,n], R[i,m], R[k,m], Q[i,k])
            # Mixed
            mixed_sum = 0.0
            for j in range(K):
                for n in range(M):
                    mixed_sum += v[j] * b[n] * I4_numpy_old(
                        Q[j,j], T[n,n], Q[i,i], Q[k,k],
                        R[j,n], Q[j,i], Q[j,k], R[i,n], R[k,n], Q[i,k])
            G[i, k] = v[i] * v[k] * (ss_sum + tt_sum - 2.0 * mixed_sum)
    return G


def generalization_error_numpy_old(Q, R, T, v, b, K, M):
    """Compute generalization error (numpy version)."""
    eps_g = 0.0
    for j in range(K):
        for l in range(K):
            eps_g += v[j] * v[l] * I2_numpy_old(Q[j,j], Q[l,l], Q[j,l])
    for n in range(M):
        for m in range(M):
            eps_g += b[n] * b[m] * I2_numpy_old(T[n,n], T[m,m], T[n,m])
    for j in range(K):
        for n in range(M):
            eps_g -= 2.0 * v[j] * b[n] * I2_numpy_old(Q[j,j], T[n,n], R[j,n])
    return eps_g

